<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { onHide, onLoad, onShow, onUnload } from '@dcloudio/uni-app'
import StoreLayout from '../../components/StoreLayout.vue'
import { money } from '../../services/catalog'
import { cancelOrder, demoState, payOrder, receiveOrder, fetchOrder, fetchRefundData, requestRefund, cancelRefund, statusLabel, type RefundItemRow, type RefundRecord } from '../../services/shop'
import { openPage, toast } from '../../services/routes'
const id = ref(''); const now = ref(Date.now()); let timer: ReturnType<typeof setInterval> | undefined
const order = computed(() => demoState.orders.find(o => o.id === id.value))
const refundOpen = ref(false), refundBusy = ref(false)
const refundItems = ref<RefundItemRow[]>([]), refundRecords = ref<RefundRecord[]>([])
const refundQty = reactive<Record<string, number>>({})
const reasonCode = ref('buyer_change'), reasonText = ref('')
const reasonOptions = [{ code: 'buyer_change', label: '不想要了/拍错' }, { code: 'buyer_size', label: '规格不合适' }, { code: 'seller_wrong', label: '发错货' }, { code: 'seller_quality', label: '质量问题' }, { code: 'seller_size', label: '发错规格' }, { code: 'buyer_other', label: '其他' }]
const reasonLabel = (code: string) => reasonOptions.find(o => o.code === code)?.label || code
const refundStatusLabel: Record<string, string> = { pending: '待审核', done: '已退款', rejected: '已拒绝', cancelled: '已撤销' }
function pendingQty(itemId: string) { return refundRecords.value.filter(r => r.status === 'pending').reduce((sum, r) => sum + (r.lines.find(l => l.itemId === itemId)?.qty || 0), 0) }
function availableQty(item: RefundItemRow) { return Math.max(0, item.qty - (item.refundedQty || 0) - pendingQty(item._id)) }
const refundable = computed(() => refundItems.value.some(item => availableQty(item) > 0))
const refundedTotal = computed(() => refundRecords.value.filter(r => r.status === 'done').reduce((sum, r) => sum + r.totalAmount, 0))
async function loadRefundData() { if (!id.value) return; try { const data = await fetchRefundData(id.value); refundItems.value = data.items; refundRecords.value = data.refunds; for (const item of data.items) if (!(item._id in refundQty)) refundQty[item._id] = 0 } catch { /* 退款区读取失败不阻塞订单详情 */ } }
async function submitRefund() {
  const lines = refundItems.value.filter(item => (refundQty[item._id] || 0) > 0).map(item => ({ itemId: item._id, qty: refundQty[item._id] }))
  if (!lines.length) { toast('请先选择要退的商品和数量'); return }
  if (refundBusy.value) return
  refundBusy.value = true
  try { const res = await requestRefund(id.value, lines, reasonCode.value, reasonText.value.trim()); toast(res.refundMode === 'instant' ? '退款已完成，金额已按支付构成退回' : '退款申请已提交，等待商家审核'); refundOpen.value = false; for (const key of Object.keys(refundQty)) refundQty[key] = 0; await Promise.all([fetchOrder(id.value), loadRefundData()]) }
  catch (error) { toast(error instanceof Error ? error.message : '申请失败') }
  finally { refundBusy.value = false }
}
async function doCancelRefund(record: RefundRecord) {
  if (refundBusy.value) return
  refundBusy.value = true
  try { await cancelRefund(id.value, record._id); toast('退款申请已撤销'); await loadRefundData() }
  catch (error) { toast(error instanceof Error ? error.message : '撤销失败') }
  finally { refundBusy.value = false }
}
const remaining = computed(() => { const seconds = order.value ? Math.max(0, Math.ceil(((order.value.payDeadline || order.value.createdAt) - now.value) / 1000)) : 0; return Math.floor(seconds / 60) + ':' + String(seconds % 60).padStart(2, '0') })
function stop() { if (timer) clearInterval(timer); timer = undefined }
function tick() { now.value = Date.now() }
async function pay() { try { await payOrder(id.value); toast('模拟支付成功，账本已更新') } catch (error) { toast(error instanceof Error ? error.message : '模拟支付失败') } }
type OrderRow = typeof demoState.orders[number]; type OrderLineRow = OrderRow['lines'][number]
function openLine(ord: OrderRow, line: OrderLineRow) { openPage('/pages/product/index?id=' + line.productId) }
function cancel() { uni.showModal({ title: '取消订单', content: '确认取消这笔待付款订单？', success: async result => { if (result.confirm) { try { await cancelOrder(id.value) } catch (error) { toast(error instanceof Error ? error.message : '取消失败') } } } }) }
function receive() { uni.showModal({ title: '确认收货', content: '确认这笔订单已收到？', success: async result => { if (result.confirm) { try { await receiveOrder(id.value) } catch (error) { toast(error instanceof Error ? error.message : '确认失败') } } } }) }
function tracking() { if (order.value && order.value.tracking) uni.setClipboardData({ data: order.value.carrier + ' ' + order.value.tracking, success: () => toast('已复制快递单号，可到快递官方渠道查询') }) }
onLoad(options => { id.value = options && typeof options.id === 'string' ? options.id : '' })
onShow(() => { stop(); tick(); fetchOrder(id.value).catch(error => toast(error instanceof Error ? error.message : '订单读取失败')); loadRefundData(); timer = setInterval(tick, 1000) })
onHide(stop); onUnload(stop)
</script>
<template><StoreLayout id="store-layout" title="订单详情" active="account" :actions="!!order && (order.status === 'pending' || order.status === 'shipped')"><view v-if="order && demoState.user"><view class="order-status"><text class="large-title">{{ statusLabel[order.status] }}</text><text v-if="order.status === 'pending'" class="small">请在 {{ remaining }} 内完成模拟支付</text><text v-if="order.status === 'refund'" class="small">退款申请已提交，处理结果以商家审核为准</text></view><view class="section"><view class="address-card"><text class="line-name">{{ order.address.name }} {{ order.address.phone.slice(0, 3) }}****{{ order.address.phone.slice(-4) }}</text><text class="paragraph small muted">{{ order.address.region }} · {{ order.address.detail }}</text></view><view v-for="(line, index) in order.lines" :key="index" class="order-line" @click="openLine(order, line)"><image :src="line.image" class="line-image" mode="aspectFit" /><view class="line-body"><text class="line-name">{{ line.name }}</text><text class="small muted">{{ line.spec }}</text><text class="small">¥{{ money(line.unitPrice) }} × {{ line.quantity }}</text></view></view><view class="bill"><view class="row between"><text>商品</text><text>¥{{ money(order.subtotal) }}</text></view><view class="row between"><text>运费</text><text>¥{{ money(order.shipping) }}</text></view><view class="row between"><text>应付金额</text><text class="blue">¥{{ money(order.total) }}</text></view><view v-if="refundedTotal" class="row between"><text>已退款</text><text class="blue">¥{{ money(refundedTotal) }}</text></view></view><text class="paragraph small muted">订单号：{{ order.id }}</text><text class="paragraph small muted">创建时间：{{ new Date(order.createdAt).toLocaleString() }}</text><text class="paragraph small muted">备注：{{ order.remark || '无' }}</text><view v-if="order.tracking" class="address-card"><text class="line-name">物流信息</text><text class="paragraph small">{{ order.carrier }} · {{ order.tracking }}</text><button class="secondary full" @click="tracking">复制单号并查件</button><text class="paragraph small muted">请前往快递官方渠道查询，当前未接物流轨迹接口。</text></view><template v-if="order.status === 'processing' || order.status === 'shipped' || order.status === 'completed'"><button v-if="refundable" class="secondary full" @click="refundOpen = !refundOpen">{{ refundOpen ? '收起退款申请' : '申请退款（可按件退）' }}</button><view v-if="refundOpen" class="refund-panel"><text class="block-title">选择要退的商品</text><view v-for="item in refundItems" :key="item._id" class="order-line"><image :src="item.image" class="line-image" mode="aspectFit" /><view class="line-body"><text class="line-name">{{ item.name }}</text><text class="small muted">{{ [item.color, item.size, item.pattern].filter(Boolean).join(' / ') }} · ¥{{ money(item.price) }} × {{ item.qty }}<template v-if="item.refundedQty"> · 已退 {{ item.refundedQty }}</template><template v-if="pendingQty(item._id)"> · 审核中 {{ pendingQty(item._id) }}</template></text><view class="stepper"><button :disabled="(refundQty[item._id] || 0) <= 0" aria-label="减少退款数量" @click="refundQty[item._id] = Math.max(0, (refundQty[item._id] || 0) - 1)">−</button><text>{{ refundQty[item._id] || 0 }}</text><button :disabled="(refundQty[item._id] || 0) >= availableQty(item)" aria-label="增加退款数量" @click="refundQty[item._id] = Math.min(availableQty(item), (refundQty[item._id] || 0) + 1)">＋</button></view></view></view><text class="field-label">退款原因</text><view class="chips"><button v-for="option in reasonOptions" :key="option.code" class="chip" :class="{ chosen: reasonCode === option.code }" @click="reasonCode = option.code">{{ option.label }}</button></view><input v-model="reasonText" class="form-input" maxlength="300" placeholder="补充说明（选填）" /><text class="paragraph small muted">{{ order.status === 'processing' ? '未发货：所选商品直接退款到账；整单全部退完时，运费一并退回。' : '已发货退款需商家审核；若是商家问题（发错货/质量问题/发错规格），审核通过后另补一份退货运费。退款金额由服务器按实付分摊计算。' }}</text><button class="primary full" :disabled="refundBusy" @click="submitRefund">{{ refundBusy ? '提交中' : '提交退款申请' }}</button></view></template><view v-if="refundRecords.length" class="refund-history"><text class="block-title">退款记录</text><view v-for="record in refundRecords" :key="record._id" class="refund-record"><text class="small"><text class="blue">{{ refundStatusLabel[record.status] || record.status }}</text> · {{ reasonLabel(record.reasonCode) }} · 合计 ¥{{ money(record.totalAmount) }}</text><text v-for="(line, li) in record.lines" :key="li" class="paragraph small muted">{{ line.name }} · {{ [line.color, line.size, line.pattern].filter(Boolean).join(' / ') }} × {{ line.qty }} · ¥{{ money(line.amount) }}</text><text class="paragraph small muted">商品 ¥{{ money(record.goodsAmount) }}<template v-if="record.freightAmount"> · 运费 ¥{{ money(record.freightAmount) }}</template><template v-if="record.freightComp"> · 退货运费补偿 ¥{{ money(record.freightComp) }}</template><template v-if="record.balanceAmount > 0"> · 退余额 ¥{{ money(record.balanceAmount) }} / 原路 ¥{{ money(record.originalAmount) }}</template><template v-else> · 原路退回 ¥{{ money(record.originalAmount) }}</template></text><text v-if="record.rejectReason" class="paragraph small">拒绝理由：{{ record.rejectReason }}</text><button v-if="record.status === 'pending'" class="primary full cancel-refund" :disabled="refundBusy" @click="doCancelRefund(record)">撤销退款</button></view></view><button class="secondary full" @click="openPage('/pages/faq/index')">订单问题 / 联系客服</button><button class="text-button full" @click="openPage('/pages/orders/index')">查看全部订单</button></view></view><view v-else class="empty-state"><text>订单不存在或尚未登录</text><button class="primary" @click="openPage('/pages/orders/index')">返回订单列表</button></view><template #bar><view v-if="order && order.status === 'pending'" class="action-bar"><button class="secondary cancel-order" @click="cancel">取消订单</button><button class="primary pay-order" @click="pay">模拟支付 ¥{{ money(order.total) }}</button></view><view v-if="order && order.status === 'shipped'" class="action-bar"><button class="primary" @click="receive">确认收货</button></view></template></StoreLayout></template>
